/// Painel local sem dependências externas. O roteiro chega somente após PIN.
const remoteWebPage = r'''
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FlowText Remote Studio</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#111318;color:#eee;font:16px system-ui,sans-serif}header{padding:16px 22px;border-bottom:1px solid #333;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h1{font-size:20px;margin:0}small,#status{color:#aab4c1}main{padding:16px;display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:16px;max-width:1500px;margin:auto}section,aside{background:#1b1e25;border:1px solid #333842;border-radius:12px;padding:16px}#reader{height:54vh;background:#070809;border-radius:8px;overflow:auto;padding:20vh 24px 40vh;text-align:center;font-size:28px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere;touch-action:pan-y}#reader span{cursor:pointer}#reader span:hover{background:#374151}.read{color:#9ca3af}.active{background:#16a34a;color:#fff;border-radius:3px}.target{outline:1px solid #59c994;border-radius:3px}button,input,select,textarea{font:inherit}#scriptEditor{margin-top:16px;border-top:1px solid #333842;padding-top:16px}#scriptDraft{display:block;width:100%;min-height:240px;resize:vertical;background:#101216;color:#eee;border:1px solid #545b66;border-radius:8px;padding:12px;line-height:1.6}#editActions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}#editStatus{color:#fbbf24;min-height:1.4em}button{color:#fff;background:#343943;border:1px solid #545b66;border-radius:8px;padding:10px;cursor:pointer}button:disabled,input:disabled,select:disabled{opacity:.45;cursor:default}button.primary{background:#166534}input[type=range]{width:100%;accent-color:#4ade80}input[type=password]{max-width:140px;padding:9px;border-radius:6px}label{display:block;margin-top:14px}#controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.muted{color:#aab4c1;font-size:13px}#progress{display:flex;justify-content:space-between;gap:12px;margin-top:12px}#pair{display:flex;gap:8px;flex-wrap:wrap;align-items:center}#message{color:#fbbf24;min-height:1.4em}#mirrorView{transform:scaleX(-1)}@media(max-width:740px){main{grid-template-columns:1fr}#reader{height:47vh}header{padding:12px}section,aside{padding:10px}}
</style></head><body><header><div><h1>Oitosete FlowText</h1><small>Remote Studio · Rede local</small></div><div id="pair"><input id="pin" type="password" inputmode="numeric" maxlength="6" placeholder="PIN de 6 dígitos" aria-label="PIN"><button id="connect" class="primary">Conectar</button><button id="disconnect">Sair</button><span id="status">Desconectado</span></div></header><main><section><div class="muted">Monitor sincronizado do roteiro · clique em uma palavra ou role para reposicionar.</div><div id="reader" tabindex="0" aria-label="Roteiro"></div><div id="progress"><span id="position">Sem roteiro</span><span id="record"></span></div><input type="range" id="seek" min="0" max="0" value="0" aria-label="Posição no roteiro" data-control><div id="controls"><button data-cmd="seek_paragraph" data-value="-1" data-control>↶ Parágrafo</button><button id="play" class="primary" data-control>Iniciar</button><button data-cmd="seek_paragraph" data-value="1" data-control>Parágrafo ↷</button><button data-cmd="undo_seek" data-control>Desfazer</button><button data-cmd="seek_word" data-value="0" data-control>Início</button><button id="end" data-control>Final</button></div><button id="editScript" data-control>Editar roteiro</button><div id="scriptEditor" hidden><strong>Editor de roteiro</strong><p class="muted">Edite ou cole o texto. Para salvar, pause a leitura e encerre a gravação. Ao alterar o roteiro, o leitor retorna ao início; depois, selecione a palavra de retomada.</p><textarea id="scriptDraft" maxlength="100000" aria-label="Editar roteiro" spellcheck="true"></textarea><div id="editActions"><button id="saveScript" class="primary">Salvar no aparelho</button><button id="reloadScript">Recarregar do aparelho</button><button id="closeEditor">Cancelar</button></div><p id="editStatus" role="status"></p></div><p id="message" role="status"></p><div class="muted">Espaço: iniciar/pausar · ↑/↓: voltar/avançar parágrafo. A prévia replica o texto, não o vídeo da câmera.</div></section><aside><strong>Configurações</strong><label>Modo <select id="mode" data-control><option value="voice">Voz</option><option value="speed">Velocidade</option></select></label><label>Fonte: <output id="fontOut">36</output><input type="range" id="font" min="12" max="200" value="36" data-control></label><label>Velocidade: <output id="speedOut">40</output><input type="range" id="speed" min="10" max="140" value="40" data-control></label><label><input type="checkbox" id="mirror" data-control> Espelhar no apresentador</label><label><button id="rec" data-control>Iniciar gravação</button></label><p class="muted">Gravação somente com autorização no aparelho principal. Use uma rede Wi-Fi confiável; o tráfego local não é criptografado.</p></aside></main>
<script>
'use strict';
const $=id=>document.getElementById(id), reader=$('reader');let ws=null, paired=false, desired=false, pin='', retry=0, timer, heartbeat, lastPong=0, seq=0, state={}, words=[], oldScript=null, oldIndex=-1, oldHighlight=-1, userScroll=false, scrollTimer, suppressUntil=0;
let editRevision=null,pendingEdit=null,editBase='',awaitingSave=false;
let clientId;try{clientId=sessionStorage.getItem('flowtext-id');}catch(e){}if(!clientId){clientId=Array.from(crypto.getRandomValues(new Uint8Array(20)),v=>v.toString(16).padStart(2,'0')).join('');try{sessionStorage.setItem('flowtext-id',clientId);}catch(e){}}
try{$('pin').value=sessionStorage.getItem('flowtext-pin')||'';}catch(e){}
function status(s){$('status').textContent=s;document.querySelectorAll('[data-control]').forEach(x=>x.disabled=!paired);if(paired){$('rec').disabled=state.mode!=='camera'||(!state.recording&&!state.allowRemoteRecording);$('mode').disabled=!!state.recording;}syncEditor();}
function send(type,value){if(!paired||!ws||ws.readyState!==1)return null;const id=++seq;try{ws.send(JSON.stringify({v:1,id,type,value}));return id;}catch(e){return null;}}
function disconnect(clear=true){if(clear&&editorOpen()&&$('scriptDraft').value!==editBase&&!confirm('Descartar o rascunho não salvo?'))return; if(clear)closeEditor();desired=false;paired=false;clearTimeout(timer);clearInterval(heartbeat);let old=ws;ws=null;if(old)old.close();if(clear){$('pin').value='';try{sessionStorage.removeItem('flowtext-pin');}catch(e){}reader.replaceChildren();words=[];oldScript=null;oldIndex=oldHighlight=-1;state={};$('position').textContent='Sem roteiro';}status('Desconectado');}
function reconnect(){if(!desired)return; if(pendingEdit!==null){pendingEdit=null;awaitingSave=true;}clearTimeout(timer);clearInterval(heartbeat);const old=ws;ws=null;paired=false;if(old)old.close();open();}
function schedule(){clearTimeout(timer);if(!desired)return;if(pendingEdit!==null){pendingEdit=null;awaitingSave=true;}paired=false;status('Reconectando…');timer=setTimeout(open,Math.min(8000,1000*2**Math.min(retry++,3)));}
function open(){if(!desired)return;status('Conectando…');const sock=new WebSocket('ws://'+location.host+'/remote');ws=sock;const watchdog=setTimeout(()=>{if(ws===sock&&!paired)sock.close();},8000);sock.onopen=()=>sock.send(JSON.stringify({v:1,type:'pair',pin,clientId}));sock.onmessage=e=>{if(ws!==sock)return;let m;try{m=JSON.parse(e.data)}catch(err){return}if(m.type==='paired'){clearTimeout(watchdog);paired=true;retry=0;lastPong=Date.now();status('Conectado');clearInterval(heartbeat);heartbeat=setInterval(()=>{if(ws!==sock)return;if(Date.now()-lastPong>25000){reconnect();return;}sock.send(JSON.stringify({v:1,type:'ping'}));},8000);}else if(m.type==='pong'){lastPong=Date.now();}else if(m.type==='pair_denied'){disconnect(false);$('message').textContent=m.message||'PIN recusado';}else if(m.type==='busy'){$('message').textContent=m.message;}else if(m.type==='state'&&paired){render(m.state);}else if(m.type==='ack'){if(m.id===pendingEdit){pendingEdit=null;awaitingSave=false;if(m.ok){closeEditor();$('message').textContent='Roteiro salvo no aparelho.';syncEditor();}else{$('message').textContent=m.message||'Não foi possível salvar';syncEditor();}}else if(!m.ok){$('message').textContent=m.message||'Comando recusado';}}};sock.onclose=()=>{clearTimeout(watchdog);if(ws!==sock)return;clearInterval(heartbeat);ws=null;schedule();};sock.onerror=()=>sock.close();}
function connect(){pin=$('pin').value.trim();if(!/^\d{6}$/.test(pin)){$('message').textContent='Informe o PIN de seis dígitos.';return;}disconnect(false);desired=true;retry=0;$('message').textContent='';try{sessionStorage.setItem('flowtext-pin',pin);}catch(e){}open();}
$('connect').onclick=connect;$('disconnect').onclick=()=>disconnect();$('pin').onkeydown=e=>{if(e.key==='Enter')connect();};document.addEventListener('visibilitychange',()=>{if(!document.hidden&&desired)reconnect();});window.addEventListener('online',()=>{if(desired)reconnect();});
function editorOpen(){return !$('scriptEditor').hidden;}
function closeEditor(){$('scriptEditor').hidden=true;$('scriptDraft').value='';editRevision=null;editBase='';pendingEdit=null;awaitingSave=false;}
function loadEditor(){editRevision=state.scriptRevision;editBase=state.script||'';$('scriptDraft').value=editBase;pendingEdit=null;awaitingSave=false;syncEditor();}
function syncEditor(){
  $('editScript').disabled=!paired||!Number.isInteger(state.scriptRevision)||editorOpen();
  if(!editorOpen())return;
  const draft=$('scriptDraft').value, busy=pendingEdit!==null, ready=paired&&Number.isInteger(state.scriptRevision);
  if(awaitingSave&&ready&&state.script===draft&&state.scriptEditable){closeEditor();$('message').textContent='Roteiro salvo no aparelho.';syncEditor();return;}
  if(awaitingSave&&ready&&state.scriptEditable)awaitingSave=false;
  const conflict=ready&&(state.scriptRevision!==editRevision||state.script!==editBase);
  $('scriptDraft').disabled=busy;
  $('saveScript').disabled=!ready||busy||awaitingSave||conflict||!state.scriptEditable||!draft.trim()||draft.length>100000||draft===editBase;
  $('reloadScript').disabled=!ready||busy;
  $('closeEditor').disabled=busy;
  $('editStatus').textContent=busy?'Salvando no aparelho…':!ready?'Sem conexão. Seu rascunho foi mantido.':awaitingSave?'Verificando o salvamento…':conflict?'O roteiro no aparelho mudou. Copie seu rascunho antes de recarregar.':!state.scriptEditable?'Pause a leitura e encerre a gravação para salvar.':draft.length.toLocaleString('pt-BR')+' / 100.000 caracteres';
}
$('editScript').onclick=()=>{$('scriptEditor').hidden=false;loadEditor();$('scriptDraft').focus();};
$('scriptDraft').oninput=syncEditor;
$('reloadScript').onclick=()=>{if($('scriptDraft').value===editBase||confirm('Substituir o rascunho pela versão do aparelho?'))loadEditor();};
$('closeEditor').onclick=()=>{if($('scriptDraft').value===editBase||confirm('Descartar alterações não salvas?')){closeEditor();syncEditor();}};
$('saveScript').onclick=()=>{if($('saveScript').disabled)return;pendingEdit=send('set_script',{revision:editRevision,text:$('scriptDraft').value});syncEditor();};
function center(i){if(!words[i])return;suppressUntil=Date.now()+400;const r=reader.getBoundingClientRect(),w=words[i].getBoundingClientRect();reader.scrollTop+=w.top-r.top-reader.clientHeight*.36;}
function render(s){state=s;const script=s.script||'';if(script!==oldScript){oldScript=script;oldIndex=oldHighlight=-1;words=[];reader.replaceChildren();let at=0;for(const [start,end] of s.wordOffsets||[]){reader.append(document.createTextNode(script.slice(at,start)));const span=document.createElement('span');span.textContent=script.slice(start,end);span.dataset.index=words.length;words.push(span);reader.append(span);at=end;}reader.append(document.createTextNode(script.slice(at)));}
const i=Math.max(0,s.readingIndex||0),h=s.highlightIndex??-1;if(oldIndex!==i||oldHighlight!==h){words[oldIndex]?.classList.remove('target');words[oldHighlight]?.classList.remove('active');if(oldHighlight!==h){for(let j=Math.max(0,Math.min(oldHighlight,h));j<=Math.max(oldHighlight,h)&&j<words.length;j++)words[j].classList.toggle('read',j<h);}words[i]?.classList.add('target');words[h]?.classList.add('active');oldIndex=i;oldHighlight=h;if(!userScroll)center(h>=0?h:i);}
$('position').textContent=words.length?`${Math.min(i+1,words.length)} / ${words.length} palavras`:'Sem roteiro';$('seek').max=Math.max(0,words.length-1);if(document.activeElement!==$('seek'))$('seek').value=i;$('play').textContent=s.playing?'Pausar':'Iniciar';$('record').textContent=s.recording?'● Gravando':'';$('rec').textContent=s.recording?'Encerrar gravação':'Iniciar gravação';$('mode').value=s.scrollMode||'voice';$('mirror').checked=!!s.mirror;for(const k of ['font','speed']){let v=k==='font'?s.fontSize:s.speed;if(document.activeElement!==$(k))$(k).value=v;$(k+'Out').textContent=Math.round(v||0);}const size=Math.max(12,Math.min(120,(s.fontSize||36)*reader.clientWidth/Math.max(s.viewportWidth||320,320)))+'px';if(reader.style.fontSize!==size){suppressUntil=Date.now()+400;reader.style.fontSize=size;if(!userScroll)center(h>=0?h:i);}status('Conectado');document.querySelector('[data-cmd="undo_seek"]').disabled=!s.undoAvailable;}
function seek(i){if(!paired)return;userScroll=false;clearTimeout(scrollTimer);send('seek_word',i);center(i);}
reader.addEventListener('click',e=>{if(e.target.dataset.index!==undefined)seek(Number(e.target.dataset.index));});function markScroll(){if(!paired)return;userScroll=true;clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{const r=reader.getBoundingClientRect(),y=r.top+r.height*.36;let best=-1,dist=Infinity;for(let i=0;i<words.length;i++){let w=words[i].getBoundingClientRect();let d=Math.abs(w.top-y);if(d<dist){dist=d;best=i;}}if(best>=0)seek(best);else userScroll=false;},250);}
reader.addEventListener('wheel',()=>{suppressUntil=0;markScroll();},{passive:true});reader.addEventListener('touchmove',()=>{suppressUntil=0;markScroll();},{passive:true});reader.addEventListener('scroll',()=>{if(Date.now()>suppressUntil)markScroll();},{passive:true});
$('seek').oninput=()=>{userScroll=true;center(Number($('seek').value));};$('seek').onchange=()=>seek(Number($('seek').value));$('play').onclick=()=>send(state.playing?'pause':'play');$('end').onclick=()=>seek(words.length-1);$('mirror').onchange=()=>send('set_mirror',$('mirror').checked);$('mode').onchange=()=>send('set_scroll_mode',$('mode').value);$('rec').onclick=()=>send(state.recording?'record_stop':'record_start');for(const k of ['font','speed']){$(k).oninput=()=>$(k+'Out').textContent=$(k).value;$(k).onchange=()=>send(k==='font'?'set_font_size':'set_speed',Number($(k).value));}document.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>send(b.dataset.cmd,b.dataset.value===undefined?undefined:Number(b.dataset.value)));document.addEventListener('keydown',e=>{if(!paired||['INPUT','SELECT','BUTTON','TEXTAREA'].includes(e.target.tagName))return;if(e.key===' '){e.preventDefault();$('play').click();}else if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();send('seek_paragraph',e.key==='ArrowUp'?-1:1);}});status('Desconectado');if(/^\d{6}$/.test($('pin').value))connect();
</script></body></html>
''';
